module screw_down_clip() {
    // Base of the clip
    difference() {
        cylinder(h = clip_width, r = clip_width_half, center = true);
        cylinder(h = clip_width, r = clip_width_half - wall_thickness, center = true);
    }

    // Screw hole
    translate([0, 0, -wall_thickness_half]) {
        cylinder(h = clip_width, r = screw_hole_radius, center = true);
    }

    // Tab to push the cable in
    translate([0, 0, clip_width_half]) {
        difference() {
            cylinder(h = tab_length, r = opening_diameter_half, center = true);
            cylinder(h = tab_length, r = opening_diameter_half - wall_thickness, center = true);
        }
    }

    // Cable guide
    translate([0, 0, clip_width_half]) {
        difference() {
            cylinder(h = cable_diameter, r = cable_diameter_half, center = true);
            cylinder(h = cable_diameter, r = cable_diameter_half - wall_thickness, center = true);
        }
    }
}

